#!/usr/bin/env bash
# D4 concurrent-position guard — SELF-CONTAINED apply (run by OPERATOR; no scp).
# Stream from the operator's Desktop:
#   Get-Content $HOME\Desktop\d4apply.sh -Raw|ssh azureuser@trading.jacksumner.com "tr -d '\r'|bash"
# Drift-gates prod==BASE, backs up *.bak-pre-d4-2026-06-20, md5-verified atomic
# install of 2 .py + surgical YAML OFF-flag insert, re-verifies. NO restart.
set -euo pipefail
PROD="/home/azureuser/trading_corp"; cd "$PROD"
OBS="trading_corp/agents/divisions/bitunix_futures_observer.py"
MAIN="trading_corp/main.py"
YAML="config/strategies.yaml"
BASE_OBS=a31a10f1445f0263389c377c41f742f8
BASE_MAIN=f16e9c24f81e65c9eb9d98019eea4e23
BASE_YAML=3cc3689aaebba2b8533eab95d258cff4
TGT_OBS=e88a7abca643f2048facfcb19a6c559b
TGT_MAIN=97a4d67661361414e369d9e4355e7d3e
BAK=.bak-pre-d4-2026-06-20
echo "== D4 apply: drift-gate (prod must == BASE) =="
md5sum $OBS $MAIN $YAML
[ "$(md5sum $OBS|awk '{print $1}')" = "$BASE_OBS" ] || { echo "ABORT: observer drift"; exit 2; }
[ "$(md5sum $MAIN|awk '{print $1}')" = "$BASE_MAIN" ] || { echo "ABORT: main drift"; exit 2; }
[ "$(md5sum $YAML|awk '{print $1}')" = "$BASE_YAML" ] || { echo "ABORT: yaml drift"; exit 2; }
echo "== backup (cp -n, preserves first backup on re-run) =="
cp -n $OBS $OBS$BAK; cp -n $MAIN $MAIN$BAK; cp -n $YAML $YAML$BAK
echo "== decode staged files =="
base64 -d > "$OBS.d4new" <<'B64OBS'
