B64MAIN
echo "== py_compile staged =="
python3 -m py_compile "$OBS.d4new" "$MAIN.d4new"
echo "== verify staged md5 == TARGET (b64 integrity) =="
[ "$(md5sum "$OBS.d4new"|awk '{print $1}')" = "$TGT_OBS" ] || { echo "ABORT: observer target mismatch"; rm -f "$OBS.d4new" "$MAIN.d4new"; exit 3; }
[ "$(md5sum "$MAIN.d4new"|awk '{print $1}')" = "$TGT_MAIN" ] || { echo "ABORT: main target mismatch"; rm -f "$OBS.d4new" "$MAIN.d4new"; exit 3; }
echo "== atomic install (.py) =="
mv "$OBS.d4new" "$OBS"; mv "$MAIN.d4new" "$MAIN"
echo "== surgical yaml insert (OFF flag) =="
python3 - "$YAML" <<'PYEOF'
import sys
PATH=sys.argv[1]
ANCHOR="\n  division: bitunix_futures\n"
BLOCK=("\n  # D4 (2026-06-20) - concurrent-position guard (same-side, bot's-own).\n"
       "  # Blocks a NEW entry when the bot already holds an open same-symbol\n"
       "  # SAME-SIDE position it opened. Ships OFF; flip after 1 clean trade.\n"
       "  concurrent_position_guard:\n    enabled: false\n  division: bitunix_futures\n")
s=open(PATH,encoding='utf-8').read()
if 'concurrent_position_guard' in s:
    print('yaml: already present, no-op'); sys.exit(0)
if s.count(ANCHOR)!=1:
    print('ABORT yaml: anchor count', s.count(ANCHOR)); sys.exit(4)
d=s.replace(ANCHOR,BLOCK,1)
import yaml
if yaml.safe_load(d)['bitunix_futures']['concurrent_position_guard']['enabled'] is not False:
    print('ABORT yaml: flag not False'); sys.exit(5)
if d.replace(BLOCK,ANCHOR,1)!=s:
    print('ABORT yaml: diff not exactly the block'); sys.exit(6)
open(PATH,'w',encoding='utf-8').write(d)
print('yaml: inserted OFF flag')
PYEOF
echo "== re-verify =="
md5sum $OBS $MAIN
python3 -m py_compile $OBS $MAIN
python3 -c "import yaml;print('cpg.enabled =', yaml.safe_load(open('config/strategies.yaml'))['bitunix_futures']['concurrent_position_guard']['enabled'])"
echo "== D4 APPLIED (flag OFF, NO restart). Next: operator restart via az run-command, then VERIFY.md =="
